ArrayList<Particle> particles = new ArrayList<Particle>();
ArrayList<String> words = new ArrayList<String>();
let wordIndex = 0;
let bgColor = color(0, 0);
let fontName = "Helvetica";
let newWord = "";

let pixelSteps = 2;
let drawAsPoints = true;
let baseParticleSize = 8;
let particleSpeedMultiplier = 1.0;
let rainbowMode = false;
let hueShift = 0;
let showControls = true;
let particleBrightness = 255;
let particleSaturation = 255;
let trailEffect = 0;

class Particle {
  let pos = new PVector(0, 0);
  let vel = new PVector(0, 0);
  let acc = new PVector(0, 0);
  let target = new PVector(0, 0);

  closeEnoughTarget = 100;
  maxSpeed = 1.0;
  maxForce = 0.1;
  particleSize = 10;
  isKilled = false;

  let startColor = color(0);
  let targetColor = color(0);
  colorWeight = 0;
  colorBlendRate = 0.010;
  hue;

  constructor() {
    hue = random(255);
  }

  function move() {
    let proximityMult = 1;
    let distance = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
    if (distance < this.closeEnoughTarget) {
      proximityMult = distance/this.closeEnoughTarget;
    }

    let towardsTarget = new PVector(this.target.x, this.target.y);
    towardsTarget.sub(this.pos);
    towardsTarget.normalize();
    towardsTarget.mult(this.maxSpeed * proximityMult * particleSpeedMultiplier);

    let steer = new PVector(towardsTarget.x, towardsTarget.y);
    steer.sub(this.vel);
    steer.normalize();
    steer.mult(this.maxForce);
    this.acc.add(steer);

    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  function draw() {
    let currentColor;
    if (rainbowMode) {
      hue = (hue + hueShift) % 255;
      currentColor = color(hue, particleSaturation, particleBrightness);
    } else {
      currentColor = lerpColor(this.startColor, this.targetColor, this.colorWeight);
    }

    if (drawAsPoints) {
      stroke(currentColor);
      strokeWeight(particleSize * baseParticleSize/10);
      point(this.pos.x, this.pos.y);
    } else {
      noStroke();
      fill(currentColor);
      ellipse(this.pos.x, this.pos.y, particleSize * baseParticleSize/10, particleSize * baseParticleSize/10);
    }

    if (this.colorWeight < 1.0) {
      this.colorWeight = min(this.colorWeight+this.colorBlendRate, 1.0);
    }
  }

  function kill() {
    if (!this.isKilled) {
      let randomPos = generateRandomPos(width/2, height/2, (width+height)/2);
      this.target.x = randomPos.x;
      this.target.y = randomPos.y;

      this.startColor = lerpColor(this.startColor, this.targetColor, this.colorWeight);
      this.targetColor = color(0);
      this.colorWeight = 0;

      this.isKilled = true;
    }
  }
}

function generateRandomPos(x, y, mag) {
  let sourcePos = new PVector(x, y);
  var randomPos = new PVector(random(0, width), random(0, height));

  let direction = PVector.sub(randomPos, sourcePos);
  direction.normalize();
  direction.mult(mag);
  sourcePos.add(direction);

  return sourcePos;
}

function nextWord(word) {
  let pg = createGraphics(width, height);
  pg.beginDraw();
  pg.fill(0);
  pg.textSize(100);
  pg.textAlign(CENTER);
  let font = createFont(fontName, 100);
  pg.textFont(font);
  pg.text(word, width/2, height/2);
  pg.endDraw();
  pg.loadPixels();

  let newColor = color(random(255), random(255), random(255));

  let particleCount = particles.size();
  let particleIndex = 0;

  ArrayList<Integer> coordsIndexes = new ArrayList<Integer>();
  for (i = 0; i < (width*height)-1; i+= pixelSteps) {
    coordsIndexes.add(i);
  }

  for (i = 0; i < coordsIndexes.size(); i++) {
    let randomIndex = int(random)(0, coordsIndexes.size());
    let coordIndex = coordsIndexes.get(randomIndex);
    coordsIndexes.remove(randomIndex);

    if (pg.pixels[coordIndex] != 0) {
      let x = coordIndex % width;
      let y = coordIndex / width;

      let newParticle;

      if (particleIndex < particleCount) {
        newParticle = particles.get(particleIndex);
        newParticle.isKilled = false;
        particleIndex += 1;
      } else {
        newParticle = new Particle();

        var randomPos = generateRandomPos(width/2, height/2, (width+height)/2);
        newParticle.pos.x = randomPos.x;
        newParticle.pos.y = randomPos.y;

        newParticle.maxSpeed = random(4.0, 10.0);
        newParticle.maxForce = newParticle.maxSpeed*0.025;
        newParticle.particleSize = random(6, 12);
        newParticle.colorBlendRate = random(0.0025, 0.03);

        particles.add(newParticle);
      }

      newParticle.startColor = lerpColor(newParticle.startColor, newParticle.targetColor, newParticle.colorWeight);
      newParticle.targetColor = newColor;
      newParticle.colorWeight = 0;

      newParticle.target.x = x;
      newParticle.target.y = y;
    }
  }

  if (particleIndex < particleCount) {
    for (i = particleIndex; i < particleCount; i++) {
      let particle = particles.get(i);
      particle.kill();
    }
  }
}

function drawControls() {
  fill(0, 180);
  rect(10, 10, 380, 320);

  fill(255);
  textSize(16);
  textAlign(LEFT);
  text("CONTROLLI EFFETTO PARTICELLE:", 20, 35);

  textSize(14);
  text("CONTROLLI BASE", 20, 60);
  textSize(12);
  text("H: Mostra/Nascondi questo pannello", 30, 80);
  text("R: Attiva/Disattiva effetto arcobaleno", 30, 100);
  text("P: Cambia tra punti e cerchi", 30, 120);

  textSize(14);
  text("DIMENSIONI E VELOCITÀ", 20, 150);
  textSize(12);
  text("↑/↓: Dimensione particelle (" + nf(baseParticleSize, 0, 1) + ")", 30, 170);
  text("←/→: Velocità movimento (" + nf(particleSpeedMultiplier, 0, 1) + ")", 30, 190);
  text("+/-: Densità particelle (" + pixelSteps + ")", 30, 210);

  textSize(14);
  text("EFFETTI COLORE", 20, 240);
  textSize(12);
  text("[/]: Velocità cambio colore (" + nf(hueShift, 0, 1) + ")", 30, 260);
  text("S/D: Saturazione (" + nf(particleSaturation, 0, 0) + ")", 30, 280);
  text("B/N: Luminosità (" + nf(particleBrightness, 0, 0) + ")", 30, 300);
  text("T: Effetto scia (" + trailEffect + ")", 30, 320);

  if (newWord.length() > 0) {
    fill(255, 255, 0);
    text("Stai scrivendo: " + newWord + "_", 20, 350);
    text("Premi INVIO per aggiungere il testo", 20, 370);
  }
}

function setup() {
  createCanvas(1000, 500);
  colorMode(HSB);
  background(0);
  bgColor = color(0, trailEffect);

  words.add("O Amico ");
	words.add(" nel giardino ");
  words.add("del tuo cuore,");
	 words.add("non piantare altro");
  words.add("che la rosa dell'Amore");
  words.add("Baha'u'lláh");



  nextWord(words.get(wordIndex));
}

function draw() {
  fill(bgColor);
  noStroke();
  rect(0, 0, width*4, height*4);

  for (x = particles.size()-1; x > -1; x--) {
    var particle = particles.get(x);
    particle.move();
    particle.draw();

    if (particle.isKilled) {
      if (particle.pos.x < 0 || particle.pos.x > width || particle.pos.y < 0 || particle.pos.y > height) {
        particles.remove(particle);
      }
    }
  }

  if (showControls) {
    drawControls();
  }

  if (frameCount % 240 == 0) {
    wordIndex = (wordIndex + 1) % words.size();
    nextWord(words.get(wordIndex));
  }
}

function keyPressed() {
  if (key == 'h' || key == 'H') {
    showControls = !showControls;
  } else if (key == 'r' || key == 'R') {
    rainbowMode = !rainbowMode;
  } else if (key == 'p' || key == 'P') {
    drawAsPoints = !drawAsPoints;
  } else if (key == 't' || key == 'T') {
    trailEffect = (trailEffect + 51) % 256;
    bgColor = color(0, trailEffect);
  } else if (key == 's' || key == 'S') {
    particleSaturation = min(particleSaturation + 25.5, 255);
  } else if (key == 'd' || key == 'D') {
    particleSaturation = max(particleSaturation - 25.5, 0);
  } else if (key == 'b' || key == 'B') {
    particleBrightness = min(particleBrightness + 25.5, 255);
  } else if (key == 'n' || key == 'N') {
    particleBrightness = max(particleBrightness - 25.5, 0);
  } else if (keyCode == UP) {
    baseParticleSize = min(baseParticleSize + 0.5, 20);
  } else if (keyCode == DOWN) {
    baseParticleSize = max(baseParticleSize - 0.5, 2);
  } else if (keyCode == LEFT) {
    particleSpeedMultiplier = max(particleSpeedMultiplier - 0.1, 0.1);
  } else if (keyCode == RIGHT) {
    particleSpeedMultiplier = min(particleSpeedMultiplier + 0.1, 3);
  } else if (key == '[') {
    hueShift = max(hueShift - 0.1, 0);
  } else if (key == ']') {
    hueShift = min(hueShift + 0.1, 5);
  } else if (key == '+' || key == '=') {
    pixelSteps = max(pixelSteps - 1, 1);
    nextWord(words.get(wordIndex));
  } else if (key == '-' || key == '_') {
    pixelSteps = min(pixelSteps + 1, 12);
    nextWord(words.get(wordIndex));
  } else if (key == ENTER || key == RETURN) {
    if (newWord.length() > 0) {
      words.add(newWord.toUpperCase());
      newWord = "";
    }
  } else if (key == BACKSPACE) {
    if (newWord.length() > 0) {
      newWord = newWord.substring(0, newWord.length()-1);
    }
  } else if (key >= ' ' && key <= 'z') {
    newWord += key;
  }
}

function mouseDragged() {
  if (mouseButton == RIGHT) {
    for (let particle of particles) {
      if (dist(particle.pos.x, particle.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < 50) {
        particle.kill();
      }
    }
  }
}

